import org.slf4j.Logger

class EventBuilder {
    fun build(): String = "event"
}
class LogService(private val log: Logger) {
    fun processOrder() {
        val event = EventBuilder().build()
        log.debug("Processing: {}", event)
    }
    fun handle(items: List<String>) {
        val summary = items.joinToString()
        log.trace("Items: {}", summary)
    }
    fun processGuarded() {
        if (log.isDebugEnabled) {
            val event = EventBuilder().build()
            log.debug("Processing: {}", event)
        }
    }
    fun processGood(orderId: String) {
        log.debug("Processing order: {}", orderId)
    }
}
